203: // S5.1.2 Canonicalized Host Names
204: function canonicalDomain(str) {
205:   if (str == null) return null;
206:   str = str.trim().replace(/^\./,''); // S4.1.2.3 & S5.2.3: ignore leading .
207: 
208:   // convert to IDN if any non-ASCII characters
209:   if (punycode && /[\u0080-]/)
210:     str = punycode.toASCII(str);
211: 
212:   return str.toLowerCase();
213: }
