215: // S5.1.3 Domain Matching
216: function domainMatch(str, domStr, canonicalize) {
217:   if (canonicalize !== false) {
218:     str = canonicalDomain(str);
219:     domStr = canonicalDomain(domStr);
220:   }
221: 
222:   /*
223:    * "The domain string and the string are identical. (Note that both the
224:    * domain string and the string will have been canonicalized to lower case at
225:    * this point)"
226:    */
227:   if (str == domStr) return true;
228: 
229:   /* "All of the following [three] conditions hold:" (order adjusted from the RFC) */
230: 
231:   /* "* The string is a host name (i.e., not an IP address)." */
232:   if (net.isIP(str)) return false;
233: 
234:   /* "* The domain string is a suffix of the string" */
235:   var idx = str.indexOf(domStr);
236:   if (idx <= 0) return false; // it's a non-match (-1) or prefix (0)
237: 
238:   // e.g "a.b.c".indexOf("b.c") === 2
239:   // 5 === 3+2
240:   if (str.length !== domStr.length + idx) // it's not a suffix
241:     return false;
242: 
243:   /* "* The last character of the string that is not included in the domain
244:   * string is a %x2E (".") character." */
245:   if (str.substr(idx-1,1) !== '.') return false;
246:   return true;
247: }
