250: // RFC6265 S5.1.4 Paths and Path-Match
251: 
252: /*
253:  * "The user agent MUST use an algorithm equivalent to the following algorithm
254:  * to compute the default-path of a cookie:"
255:  *
256:  * Assumption: the path (and not query part or absolute uri) is passed in.
257:  */
258: function defaultPath(path) {
259:   // "2. If the uri-path is empty or if the first character of the uri-path is not
260:   // a %x2F ("/") character, output %x2F ("/") and skip the remaining steps.
261:   if (!path || path.substr(0,1) !== "/") return "/";
262: 
263:   // "3. If the uri-path contains no more than one %x2F ("/") character, output
264:   // %x2F ("/") and skip the remaining step."
265:   if (path === "/") return path;
266: 
267:   var rightSlash = path.lastIndexOf("/");
268:   if (rightSlash === 0) return "/";
269:   
270:   // "4. Output the characters of the uri-path from the first character up to,
271:   // but not including, the right-most %x2F ("/")."
272:   return path.slice(0, rightSlash);
273: }
