275: /*
276:  * "A request-path path-matches a given cookie-path if at least one of the
277:  * following conditions holds:"
278:  */
279: function pathMatch(reqPath,cookiePath) {
280:   // "o  The cookie-path and the request-path are identical."
281:   if (cookiePath === reqPath)
282:     return true;
283: 
284:   var idx = reqPath.indexOf(cookiePath);
285:   if (idx === 0) {
286:     // "o  The cookie-path is a prefix of the request-path, and the last
287:     // character of the cookie-path is %x2F ("/")."
288:     if (cookiePath.substr(-1) === "/")
289:       return true;
