291:     // " o  The cookie-path is a prefix of the request-path, and the first
292:     // character of the request-path that is not included in the cookie- path
293:     // is a %x2F ("/") character."
294:     if (reqPath.substr(cookiePath.length,1) === "/")
295:       return true;
296:   }
297: 
298:   return false;
299: }
